1	// Checks the built walk-through in Chromium at a phone's width, light and dark:
2	//   mkdir -p /tmp/walk-srv && ln -sfn "$PWD/docs" /tmp/walk-srv/fortress
3	//   python3 -m http.server 8766 --directory /tmp/walk-srv &
4	//   node explorations/microgpt-walk/check.js [URL of the walk-through] [folder for the screenshots]
5	// It fails on a page that scrolls sideways, on a script error, and on a request that leaves the site. It then
6	// writes a note, reloads, and checks the note, the place, the export's address and that the notes are kept
7	// apart from the specification reader's. It saves one screenshot of each page, light and dark.
8	// It needs Playwright (NODE_PATH, or /opt/node-tools/node_modules, or the global node_modules).
9	let pw;
10	for (const m of ['playwright', '/opt/node-tools/node_modules/playwright', '/opt/node22/lib/node_modules/playwright']) {
11	  try { pw = require(m); break; } catch (e) { /* next */ }
12	}
13	const { chromium } = pw;
14	const fs = require('fs');
15	const path = require('path');
16	const U = process.argv[2] || 'http://localhost:8766/fortress/microgpt/';
17	const SHOTS = process.argv[3] || '/tmp';
18	const OUT = path.join(__dirname, '..', '..', 'docs', 'microgpt');
19	const pages = fs.readdirSync(OUT).filter(f => f.endsWith('.html')).map(f => f.replace(/\.html$/, '')).sort();
20	let failed = 0;
21	const ok = (c, m) => { if (!c) failed++; console.log((c ? 'PASS ' : 'FAIL ') + m); };
22	(async () => {
23	  const b = await chromium.launch();
24	  const c = await b.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2, hasTouch: true, colorScheme: 'light' });
25	  const p = await c.newPage();
26	  const ext = [], errs = [];
27	  p.on('request', r => { if (!r.url().startsWith(U) && !r.url().startsWith('data:')) ext.push(r.url()); });
28	  p.on('pageerror', e => errs.push(e.message));
29	  p.on('console', m => { if (m.type() === 'error') errs.push(m.text()); });
30	  for (const scheme of ['light', 'dark']) {
31	    await p.emulateMedia({ colorScheme: scheme });
32	    for (const f of pages) {
33	      await p.goto(U + f + '.html');
34	      const w = await p.evaluate(() => document.documentElement.scrollWidth - window.innerWidth);
35	      const wide = await p.evaluate(() => Array.from(document.querySelectorAll('.dm svg, figure.fig svg')).filter(s => s.getBoundingClientRect().right > window.innerWidth).length);
36	      ok(w === 0 && wide === 0, `${scheme} ${f}: no sideways scroll (${w}); formulas or drawings wider than the screen: ${wide}`);
37	      await p.screenshot({ path: path.join(SHOTS, `walk-${f}-${scheme}.png`), fullPage: true });
38	    }
39	  }
40	  await p.emulateMedia({ colorScheme: 'light' });
41	  const first = pages.find(f => !['index', 'notes', 'listing'].includes(f) && fs.readFileSync(path.join(OUT, f + '.html'), 'utf8').includes('class="dm'));
42	  await p.goto(U + first + '.html');
43	  const gutter = await p.evaluate(() => document.querySelector('.page').getBoundingClientRect().left);
44	  ok(gutter === 16, 'gutter 16px: ' + gutter);
45	  // Select
46	  await p.locator('section.sec[data-num] > h2 button.sel').first().click();
47	  const sel = await p.evaluate(() => window.getSelection().toString());
48	  ok(sel.length > 200 && !/^\s*\d+\s*$/m.test(sel.split('\n')[0]), 'Select selects a section: ' + sel.length + ' characters');
49	  ok(!/Select|✎/.test(sel), 'the selection holds no button text');
50	  // for Speak, the Select button leaves out the formulas and the long boxes of numbers
51	  const withMath = await p.evaluate(() => { const d = document.querySelector('.dm'); return d ? d.closest('section.sec[data-num*="."]').getAttribute('data-num') : ''; });
52	  if (withMath) {
53	    await p.locator(`section.sec[data-num="${withMath}"] > h2 button.sel, section.sec[data-num="${withMath}"] > h3 button.sel`).first().click();
54	    const s2 = await p.evaluate(() => window.getSelection().toString());
55	    const svgText = await p.evaluate(() => document.querySelector('.dm svg').textContent.replace(/\s+/g, '').slice(0, 12));
56	    ok(s2.length > 100 && !s2.replace(/\s+/g, '').includes(svgText), 'the Select button leaves a formula out of its selection (' + withMath + ')');
57	    await p.evaluate(() => window.getSelection().removeAllRanges());
58	    await p.waitForTimeout(100);
59	    ok(await p.evaluate(() => !document.documentElement.classList.contains('speak')), 'a selection by hand can take the formula again');
60	  }
61	  // a note on a paragraph, kept across a reload, under the walk-through's own key
62	  await p.locator('p.nb .addnote').first().click();
63	  await p.locator('.note-edit textarea').fill('a note of the check');
64	  await p.locator('.note-edit button.primary').click();
65	  await p.evaluate(() => window.scrollTo(0, 2400));
66	  await p.waitForTimeout(700);
67	  await p.reload();
68	  ok(await p.locator('.note-card').count() === 1, 'the note is there after a reload');
69	  const keys = await p.evaluate(() => Object.keys(Object.assign({}, window.localStorage)).sort().join(' '));
70	  ok(/fortress-microgpt\.notes\.v1/.test(keys) && !/fortress-spec\./.test(keys), 'kept apart from the specification reader: ' + keys);
71	  ok(await p.locator('#resume .resume').count() === 1, 'the part offers the place where it was left');
72	  await p.goto(U + 'index.html');
73	  ok(await p.locator('#continue .resume').count() === 1, 'the start page offers to continue');
74	  await p.goto(U + 'notes.html');
75	  const text = await p.locator('#export-text').inputValue();
76	  ok(text.includes('Notes on the microGPT walk-through') && text.includes(U.replace(/^http:\/\/[^/]+/, 'https://palimondo.github.io') + first + '.html#') && !text.includes('/specification/'),
77	     'the export names the walk-through and links to its pages');
78	  const link = /Link: (\S+)/.exec(text)[1].replace('https://palimondo.github.io', new URL(U).origin);
79	  await p.goto(link);
80	  ok(await p.evaluate(() => !!document.getElementById(decodeURIComponent(location.hash.slice(1)))), 'a link of the export leads to its passage');
81	  await p.goto(U + 'listing.html');
82	  const dead = await p.evaluate(() => Array.from(document.querySelectorAll('pre.listing a.lnk')).filter(a => !a.getAttribute('href') && a.parentNode).length);
83	  console.log('listing: line numbers without a place: ' + dead);
84	  ok(ext.length === 0, 'no request leaves the site: ' + ext.slice(0, 3).join(' '));
85	  ok(errs.length === 0, 'no script error: ' + errs.slice(0, 3).join(' | '));
86	  await b.close();
87	  console.log(failed ? `FAILED: ${failed}` : 'ALL PASS');
88	  process.exit(failed ? 1 : 0);
89	})();
